SELECT p.id,p.project_id,p.owner_user_id,p.workspace_revision,p.scene_version,p.project_name,p.project_desc,
  p.video_url,p.cover_url,p.allow_copy,p.review_status,p.review_reason,p.source_publication_id,p.root_publication_id,p.create_time
 ORDER BY p.id DESC LIMIT #{offset},#{limit}
